        "highlighted": "dotnet test tests/BlueTusk.Data.Tests/BlueTusk.Data.Tests.csproj `\n  <span class=\"hljs-literal\">--configuration</span> Release `\n  <span class=\"hljs-literal\">--filter</span> <span class=\"hljs-string\">&quot;FullyQualifiedName~BlueTuskMultiplexingTests&quot;</span>\ndotnet test tests/BlueTusk.IntegrationTests/BlueTusk.IntegrationTests.csproj `\n  <span class=\"hljs-literal\">--configuration</span> Release `\n  <span class=\"hljs-literal\">--filter</span> <span class=\"hljs-string\">&quot;FullyQualifiedName~BlueTuskMultiplexingIntegrationTests&quot;</span>\n<span class=\"hljs-variable\">$env:BLUETUSK_BENCHMARK_CONNECTION_STRING</span> = <span class=\"hljs-string\">&quot;&lt;dedicated PostgreSQL connection string&gt;&quot;</span>\ndotnet run <span class=\"hljs-literal\">--project</span> benchmarks/BlueTusk.Benchmarks/BlueTusk.Benchmarks.csproj `\n  <span class=\"hljs-literal\">--configuration</span> Release <span class=\"hljs-literal\">--</span> `\n  <span class=\"hljs-literal\">--job</span> medium <span class=\"hljs-literal\">--inProcess</span> <span class=\"hljs-literal\">--filter</span> <span class=\"hljs-string\">&quot;*MultiplexingComparisonBenchmarks*&quot;</span>\ndotnet run <span class=\"hljs-literal\">--project</span> benchmarks/BlueTusk.Benchmarks/BlueTusk.Benchmarks.csproj `\n  <span class=\"hljs-literal\">--configuration</span> Release <span class=\"hljs-literal\">--no-build</span> <span class=\"hljs-literal\">--</span> `\n  <span class=\"hljs-literal\">--multiplexing-paired-evidence</span> artifacts/benchmarks/multiplexing<span class=\"hljs-literal\">-paired-evidence</span>.json\n./eng/verify<span class=\"hljs-literal\">-multiplexing-performance</span>.ps1 `\n  <span class=\"hljs-literal\">-ReportPath</span> artifacts/benchmarks/results/BlueTusk.Benchmarks.MultiplexingComparisonBenchmarks<span class=\"hljs-literal\">-report-full</span>.json `\n  <span class=\"hljs-literal\">-PairedReportPath</span> artifacts/benchmarks/multiplexing<span class=\"hljs-literal\">-paired-evidence</span>.json\n./eng/<span class=\"hljs-built_in\">test-multiplexing</span><span class=\"hljs-literal\">-performance-verifier</span>.ps1\n",
        "language": "powershell"
