        "code": "./eng/verify-v1-approval-evidence.ps1 `\n  -EvidencePath 'D:/release-evidence/approvals/application-pilot-a.json' `\n  -ExpectedGateId 'application-pilot-a' `\n  -ExpectedCommit '<40-character-candidate-sha>'\n",
